#[cfg(test)]
mod own_tests {
    use super::Strata;
    use proc_macro2::Span;
    use std::collections::HashSet;
    use syn::Ident;

    fn ident(name: &str) -> Ident {
        Ident::new(name, Span::call_site())
    }

    fn make(rels: &[Ident], deps: &[(usize, usize)]) -> Strata {
        let relations: HashSet<Ident> = rels.iter().cloned().collect();
        let dependencies: HashSet<(&Ident, &Ident)> =
            deps.iter().map(|&(a, b)| (&rels[a], &rels[b])).collect();
        Strata::new(relations, dependencies)
    }

    /// Every relation shows up in exactly one stratum, and its index agrees.
    fn check_partition(strata: &Strata, rels: &[Ident]) {
        let mut seen: Vec<Ident> = Vec::new();
        for (i, stratum) in strata.iter().enumerate() {
            for rel in stratum {
                assert_eq!(strata.find_relation(rel), i);
                seen.push(rel.clone());
            }
        }
        assert_eq!(seen.len(), rels.len());
        let seen: HashSet<Ident> = seen.into_iter().collect();
        let expected: HashSet<Ident> = rels.iter().cloned().collect();
        assert_eq!(seen, expected);
    }

    #[test]
    fn empty() {
        let strata = make(&[], &[]);
        assert_eq!(strata.iter().count(), 0);
    }

    #[test]
    fn isolated_relations() {
        let rels = vec![ident("A"), ident("B"), ident("C")];
        let strata = make(&rels, &[]);
        assert_eq!(strata.iter().count(), 3);
        for stratum in strata.iter() {
            assert_eq!(stratum.len(), 1);
        }
        check_partition(&strata, &rels);
